declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/../config/auth.php';$u=auth_require(['ADMIN']);$c=require __DIR__.'/../config/database.php';$pdo=new PDO("mysql:host={$c['host']};dbname={$c['dbname']};charset={$c['charset']}",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);function out(array$d,int$c=200):never{http_response_code($c);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}$keysFile=__DIR__.'/../config/push-keys.php';if(!is_file($keysFile))out(['ok'=>false,'error'=>'Push no configurado en el servidor'],503);$keys=require $keysFile;
try{$m=$_SERVER['REQUEST_METHOD']??'GET';if($m==='GET'){out(['ok'=>true,'publicKey'=>$keys['publicKey']??'']);}$in=json_decode(file_get_contents('php://input'),true)?:[];if($m==='POST'){$s=$in['subscription']??null;if(!is_array($s)||empty($s['endpoint'])||empty($s['keys']['p256dh'])||empty($s['keys']['auth']))out(['ok'=>false,'error'=>'Suscripción inválida'],422);$id=(string)$pdo->query('SELECT UUID()')->fetchColumn();$st=$pdo->prepare("INSERT INTO push_subscriptions(id,usuario_id,endpoint,p256dh,auth,content_encoding,user_agent,activo) VALUES(:id,:u,:e,:p,:a,:c,:ua,1) ON DUPLICATE KEY UPDATE usuario_id=VALUES(usuario_id),p256dh=VALUES(p256dh),auth=VALUES(auth),content_encoding=VALUES(content_encoding),user_agent=VALUES(user_agent),activo=1,updated_at=NOW()");$st->execute([':id'=>$id,':u'=>$u['id'],':e'=>(string)$s['endpoint'],':p'=>(string)$s['keys']['p256dh'],':a'=>(string)$s['keys']['auth'],':c'=>(string)($s['contentEncoding']??'aes128gcm'),':ua'=>substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,255)]);out(['ok'=>true]);}if($m==='DELETE'){$endpoint=trim((string)($in['endpoint']??''));if($endpoint==='')out(['ok'=>false,'error'=>'endpoint obligatorio'],422);$st=$pdo->prepare('UPDATE push_subscriptions SET activo=0 WHERE usuario_id=:u AND endpoint=:e');$st->execute([':u'=>$u['id'],':e'=>$endpoint]);out(['ok'=>true]);}out(['ok'=>false,'error'=>'Método no permitido'],405);}catch(Throwable$e){out(['ok'=>false,'error'=>$e->getMessage()],500);}